local ChaliceMaker = {}
local PRODUCTS = {
    pewter_chalice = { name = "Pustrast kelih", tinCost = 2, time = 2, cost = 35, sanctity = 4, description = "Pustrast kelih za skromne maše." },
    brass_chalice = { name = "Medeninast kelih", brassCost = 2, time = 3, cost = 90, sanctity = 7, prestige = 2, description = "Medeninast kelih z graviranjem." },
    silver_chalice = { name = "Srebrni kelih", silverCost = 2, time = 5, cost = 230, sanctity = 11, prestige = 5, happiness = 1, description = "Srebrni kelih z reliefom." },
    gold_chalice = { name = "Zlati kelih", goldCost = 1, silverCost = 1, time = 7, cost = 520, sanctity = 16, prestige = 12, happiness = 2, description = "Zlati kelih za slovesne maše." },
    jewel_chalice = { name = "Draguljni kelih", goldCost = 2, silverCost = 1, jewelCost = 2, time = 10, cost = 1100, sanctity = 21, prestige = 22, happiness = 5, description = "Kelih z dragulji za katedralo." },
    royal_papal_chalice = { name = "Kraljevski papeški kelih", goldCost = 3, silverCost = 2, jewelCost = 3, pearlCost = 1, time = 15, cost = 2700, sanctity = 34, prestige = 65, happiness = 13, description = "Veliki kraljevski papeški kelih z dragulji in biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Keliškarska delavnica", cost = { gold = 290, wood = 120 }, upkeep = 7, qualityBonus = 5 },
    forge = { name = "Keliškarska kovačija", cost = { gold = 900, wood = 220, stone = 200, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    gilding_room = { name = "Pozlatnica", cost = { gold = 1900, wood = 300, stone = 400, silver = 25, gold = 6 }, upkeep = 45, qualityBonus = 30 },
    royal_chalice_atelier = { name = "Kraljevski atelje keliho", cost = { gold = 7500, wood = 600, stone = 800, gold = 80, jewel = 25 }, upkeep = 140, qualityBonus = 55, prestigeBonus = 35 },
}
ChaliceMaker.tinStock = 12; ChaliceMaker.brassStock = 8; ChaliceMaker.silverStock = 8; ChaliceMaker.goldStock = 6; ChaliceMaker.jewelStock = 6; ChaliceMaker.pearlStock = 4
ChaliceMaker.productStock = {}; ChaliceMaker.buildings = {}; ChaliceMaker.maker = nil; ChaliceMaker.activeMaking = {}; ChaliceMaker.totalProducts = 0; ChaliceMaker.dayTimer = 0
function ChaliceMaker.init() ChaliceMaker.tinStock=12; ChaliceMaker.brassStock=8; ChaliceMaker.silverStock=8; ChaliceMaker.goldStock=6; ChaliceMaker.jewelStock=6; ChaliceMaker.pearlStock=4; ChaliceMaker.productStock={}; ChaliceMaker.buildings={}; ChaliceMaker.maker=nil; ChaliceMaker.activeMaking={}; ChaliceMaker.totalProducts=0; ChaliceMaker.dayTimer=0; print("[ChaliceMaker] Royal Chalice Maker System initialized (6 products, 4 buildings)") end
function ChaliceMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChaliceMaker.maker={name=n or ("Keliškar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Keliškar najet: %s (spretnost: %d)",ChaliceMaker.maker.name,s),"success") end; return true end
function ChaliceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChaliceMaker.build(id) local ok,e=ChaliceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChaliceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChaliceMaker.getQualityBonus() local b=0; for _,bd in ipairs(ChaliceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChaliceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.tinCost and ChaliceMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.brassCost and ChaliceMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ChaliceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChaliceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChaliceMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChaliceMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChaliceMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ChaliceMaker.maker then return false,"Potreben keliškar" end; return true end
function ChaliceMaker.make(pt,qty) qty=qty or 1; local ok,e=ChaliceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.tinCost then ChaliceMaker.tinStock=ChaliceMaker.tinStock-d.tinCost*qty end; if d.brassCost then ChaliceMaker.brassStock=ChaliceMaker.brassStock-d.brassCost*qty end; if d.silverCost then ChaliceMaker.silverStock=ChaliceMaker.silverStock-d.silverCost*qty end; if d.goldCost then ChaliceMaker.goldStock=ChaliceMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ChaliceMaker.jewelStock=ChaliceMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChaliceMaker.pearlStock=ChaliceMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ChaliceMaker.maker then t=math.max(1,t-math.floor(ChaliceMaker.maker.skill/12)) end; table.insert(ChaliceMaker.activeMaking,{id="chalice_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sanctity=d.sanctity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChaliceMaker.completeMaking(m) local q=1.0+(ChaliceMaker.getQualityBonus()/100); if ChaliceMaker.maker then q=q+(ChaliceMaker.maker.skill/180) end; q=math.min(2.0,q); ChaliceMaker.productStock[m.productType]=(ChaliceMaker.productStock[m.productType] or 0)+m.quantity; ChaliceMaker.totalProducts=ChaliceMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChaliceMaker.maker then ChaliceMaker.maker.itemsMade=ChaliceMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then ChaliceMaker.maker.skill=math.min(100,ChaliceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kelih izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chalice.completed",{productName=m.productName,sanctity=m.sanctity}) end end
function ChaliceMaker.update(dt) if not _G.state then return end; ChaliceMaker.dayTimer=ChaliceMaker.dayTimer+dt; if ChaliceMaker.dayTimer>=30 then ChaliceMaker.dayTimer=0; for i=#ChaliceMaker.activeMaking,1,-1 do local m=ChaliceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChaliceMaker.completeMaking(m); table.remove(ChaliceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChaliceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChaliceMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChaliceMaker.getStats() return {tinStock=ChaliceMaker.tinStock,brassStock=ChaliceMaker.brassStock,silverStock=ChaliceMaker.silverStock,goldStock=ChaliceMaker.goldStock,jewelStock=ChaliceMaker.jewelStock,pearlStock=ChaliceMaker.pearlStock,productStock=ChaliceMaker.productStock,numBuildings=#ChaliceMaker.buildings,hasMaker=ChaliceMaker.maker~=nil,makerName=ChaliceMaker.maker and ChaliceMaker.maker.name or "—",makerSkill=ChaliceMaker.maker and ChaliceMaker.maker.skill or 0,activeMaking=#ChaliceMaker.activeMaking,totalProducts=ChaliceMaker.totalProducts} end
return ChaliceMaker
